mapper.select:
SELECT timeline_seq, timeline_type_cd, title, content_preview, event_dt, use_yn, updated_at, updated_by, created_at, created_by FROM ( SELECT t.timeline_seq AS timeline_seq, t.timeline_type_cd AS timeline_type_cd, t.title AS title, SUBSTRING(COALESCE(t.content, '') FROM 1 FOR 200) AS content_preview, TO_CHAR(t.event_dt, 'YYYY-MM-DD') AS event_dt, COALESCE(t.use_yn, 'Y') AS use_yn, TO_CHAR(t.updated_at, 'YYYY-MM-DD HH24:MI:SS') AS updated_at, t.updated_by AS updated_by, TO_CHAR(t.created_at, 'YYYY-MM-DD HH24:MI:SS') AS created_at, t.created_by AS created_by, ROW_NUMBER() OVER (ORDER BY t.event_dt DESC, t.timeline_seq DESC) AS rn FROM adm_timeline_mst t WHERE 1=1
AND COALESCE(t.use_yn, 'Y') = #{use_yn}
AND COALESCE(t.use_yn, 'Y') = 'Y'
AND t.timeline_type_cd = #{timeline_type_cd}
AND t.title LIKE '%' || #{title} || '%'
AND t.event_dt >= TO_DATE(#{event_dt_from}, 'YYYY-MM-DD')
AND t.event_dt <= TO_DATE(#{event_dt_to}, 'YYYY-MM-DD')
) r WHERE 1=1
AND r.rn > #{offset}
AND r.rn <= (COALESCE(#{offset}, 0) + #{size})
ORDER BY r.rn

mapper.update:
UPDATE adm_timeline_mst
   SET use_yn = 'N',
       updated_at = CURRENT_TIMESTAMP,
       updated_by = #{updated_by}
 WHERE timeline_seq = #{timeline_seq}
